<?php $groups = sd_homepage_groups(); if ( empty( $groups ) ) { return; } ?><section class="sd-home-section sd-home-communities"><div class="sd-container"><?php sd_homepage_heading( __( 'Explore', 'social-discovery' ), sd_homepage_get( 'sd_home_groups_heading' ), __( 'Find public communities organized around shared interests.', 'social-discovery' ) ); ?><div class="<?php echo esc_attr( sd_homepage_grid_class( sd_homepage_get( 'sd_home_groups_columns' ) ) ); ?>"><?php foreach ( $groups as $group ) : $group_url = function_exists( 'bp_get_group_permalink' ) ? bp_get_group_permalink( $group ) : ''; ?><article class="sd-home-card sd-home-group-card"><div class="sd-home-group-cover"><?php if ( function_exists( 'bp_group_cover_url' ) ) : ?><img src="<?php echo esc_url( bp_group_cover_url( $group ) ); ?>" alt="" loading="lazy"><?php endif; ?></div><div class="sd-home-card-body"><div class="sd-home-group-icon">✦</div><h3><?php echo esc_html( bp_get_group_name( $group ) ); ?></h3><p><?php echo esc_html( wp_trim_words( bp_get_group_description( $group ), 22 ) ); ?></p><div class="sd-home-card-meta"><span><?php echo esc_html( absint( $group->total_member_count ) ); ?> <?php esc_html_e( 'members', 'social-discovery' ); ?></span><span><?php echo esc_html( ucfirst( $group->status ) ); ?></span></div><?php if ( $group_url ) : ?><a class="sd-text-link" href="<?php echo esc_url( $group_url ); ?>"><?php esc_html_e( 'View community', 'social-discovery' ); ?> <span aria-hidden="true">→</span></a><?php endif; ?></div></article><?php endforeach; ?></div></div></section>
